core_reasoning_3:
\textbf{Claim.} In a spatially homogeneous two-mutant environment with common diffusion coefficient \(D\), mutant \(1\)'s frequency satisfies the Fisher-type logistic reaction--diffusion equation
\[
\frac{\partial f_1}{\partial t}=(g_1-g_2)f_1(1-f_1)+D\frac{\partial^2 f_1}{\partial z^2}.
\]

\textbf{Premises.}
\begin{align*}
(P1)\quad & f_1(z,t)+f_2(z,t)=1.\\
(P2)\quad & g_1,g_2\in\mathbb{R}\text{ are independent of }z\text{ and }t.\\
(P3)\quad & \bar{g}(z,t):=f_1(z,t)g_1+f_2(z,t)g_2.\\
(P4)\quad & \frac{\partial f_1}{\partial t}=f_1(g_1-\bar{g})+D\frac{\partial^2 f_1}{\partial z^2}.\\
(P5)\quad & D>0.
\end{align*}

\textbf{Derivation.}
\begin{align*}
\bar{g}
&=f_1g_1+f_2g_2 && \text{by }(P3)\\
&=f_1g_1+(1-f_1)g_2 && \text{by }(P1)\\
&=g_2+f_1(g_1-g_2) && \text{algebra},\\[2mm]
g_1-\bar{g}
&=g_1-\bigl(g_2+f_1(g_1-g_2)\bigr) && \text{substitution}\\
&=(g_1-g_2)-f_1(g_1-g_2) && \text{algebra}\\
&=(g_1-g_2)(1-f_1) && \text{factorization},\\[2mm]
\frac{\partial f_1}{\partial t}
&=f_1(g_1-\bar{g})+D\frac{\partial^2 f_1}{\partial z^2} && \text{by }(P4)\\
&=f_1(g_1-g_2)(1-f_1)+D\frac{\partial^2 f_1}{\partial z^2} && \text{using the previous line}\\
&=(g_1-g_2)f_1(1-f_1)+D\frac{\partial^2 f_1}{\partial z^2} && \text{commutativity}.
\end{align*}

\textbf{Final Result.}
\[
\boxed{\displaystyle
\frac{\partial f_1}{\partial t}=(g_1-g_2)f_1(1-f_1)+D\frac{\partial^2 f_1}{\partial z^2}}
\]
\hfill$\blacksquare$

core_reasoning_8:
\textbf{Claim.} For equal diffusion and parabolic growth functions
\[
g_1(z)=m-\sigma\left(z-\frac{L}{2}\right)^2+h,
\qquad
g_2(z)=m+2\sigma\left(z-\frac{L}{2}\right)^2,
\]
with \(L>0\) and \(\sigma>0\), the first-order principal-eigenvalue comparison satisfies
\[
\lambda_1(1)>\lambda_1(2)
\quad\Longleftrightarrow\quad
h>h_c:=\frac{L^2(\pi^2-6)\sigma}{4\pi^2}.
\]

\textbf{Premises.}
\begin{align*}
(P1)\quad & L>0,
\quad \sigma>0,
\quad m,h\in\mathbb{R}.\\
(P2)\quad & g_1(z):=m-\sigma\left(z-\frac{L}{2}\right)^2+h,
\quad
 g_2(z):=m+2\sigma\left(z-\frac{L}{2}\right)^2.\\
(P3)\quad & \lambda_1(1)-\lambda_1(2)=\frac{2}{L}\int_0^L\bigl(g_1(z)-g_2(z)\bigr)\sin^2\left(\frac{\pi z}{L}\right)\,dz.\\
(P4)\quad & \int_0^L\sin^2\left(\frac{\pi z}{L}\right)\,dz=\frac{L}{2}.\\
(P5)\quad & \cos^2(x)=\frac{1+\cos(2x)}{2}.\\
(P6)\quad & \int x^2\cos(ax)\,dx=\frac{x^2\sin(ax)}{a}+\frac{2x\cos(ax)}{a^2}-\frac{2\sin(ax)}{a^3}\quad(a\neq0).\\
(P7)\quad & \pi^2-6>0.
\end{align*}

\textbf{Derivation.}
\begin{align*}
g_1(z)-g_2(z)
&=m-\sigma\left(z-\frac{L}{2}\right)^2+h-m-2\sigma\left(z-\frac{L}{2}\right)^2 && \text{by }(P2)\\
&=h-3\sigma\left(z-\frac{L}{2}\right)^2. && \text{algebra}
\end{align*}
Define
\begin{align*}
J&:=\int_0^L\left(z-\frac{L}{2}\right)^2\sin^2\left(\frac{\pi z}{L}\right)\,dz. && \text{definition}
\end{align*}
With \(x:=z-L/2\), one has \(z=x+L/2\), \(x\in[-L/2,L/2]\), and \(\sin^2(\pi z/L)=\cos^2(\pi x/L)\). Thus
\begin{align*}
J
&=\int_{-L/2}^{L/2}x^2\cos^2\left(\frac{\pi x}{L}\right)\,dx && x:=z-L/2\\
&=\int_{-L/2}^{L/2}x^2\frac{1+\cos(2\pi x/L)}{2}\,dx && \text{by }(P5)\\
&=\int_0^{L/2}x^2\,dx+\int_0^{L/2}x^2\cos\left(\frac{2\pi x}{L}\right)\,dx && \text{even integrands}. 
\end{align*}
Let \(a:=2\pi/L\). Then
\begin{align*}
\int_0^{L/2}x^2\,dx
&=\left[\frac{x^3}{3}\right]_0^{L/2}=\frac{L^3}{24},\\
\int_0^{L/2}x^2\cos(ax)\,dx
&=\left[\frac{x^2\sin(ax)}{a}+\frac{2x\cos(ax)}{a^2}-\frac{2\sin(ax)}{a^3}\right]_0^{L/2} && \text{by }(P6)\\
&=0+\frac{L\cos(\pi)}{a^2}-0 && \text{because }aL/2=\pi\text{ and }\sin\pi=0\\
&=-\frac{L}{a^2} && \cos\pi=-1\\
&=-\frac{L^3}{4\pi^2}. && a=2\pi/L
\end{align*}
Therefore
\begin{align*}
J&=\frac{L^3}{24}-\frac{L^3}{4\pi^2} && \text{combine the two integrals}\\
&=\frac{L^3(\pi^2-6)}{24\pi^2}. && \text{common denominator}
\end{align*}
Now compute the eigenvalue difference:
\begin{align*}
\lambda_1(1)-\lambda_1(2)
&=\frac{2}{L}\int_0^L\left[h-3\sigma\left(z-\frac{L}{2}\right)^2\right]\sin^2\left(\frac{\pi z}{L}\right)\,dz && \text{by }(P3)\text{ and }g_1-g_2\\
&=\frac{2h}{L}\int_0^L\sin^2\left(\frac{\pi z}{L}\right)\,dz-\frac{6\sigma}{L}J && \text{linearity}\\
&=\frac{2h}{L}\cdot\frac{L}{2}-\frac{6\sigma}{L}\cdot\frac{L^3(\pi^2-6)}{24\pi^2} && \text{by }(P4)\text{ and }J\\
&=h-\frac{L^2(\pi^2-6)\sigma}{4\pi^2}. && \text{algebra}
\end{align*}
Since \(\pi^2-6>0\) and \(\sigma>0\), define
\begin{align*}
h_c&:=\frac{L^2(\pi^2-6)\sigma}{4\pi^2}. && \text{definition}
\end{align*}
Then
\begin{align*}
\lambda_1(1)>\lambda_1(2)
&\Longleftrightarrow \lambda_1(1)-\lambda_1(2)>0 && \text{definition of } >\\
&\Longleftrightarrow h-h_c>0 && \text{by the derived difference}\\
&\Longleftrightarrow h>h_c. && \text{algebra}
\end{align*}

\textbf{Final Result.}
\[
\boxed{\displaystyle
\lambda_1(1)>\lambda_1(2)
\Longleftrightarrow
h>h_c:=\frac{L^2(\pi^2-6)\sigma}{4\pi^2}}
\]
\hfill$\blacksquare$

core_reasoning_9:
\textbf{Claim.} If the first-order eigenvalue formula is discretized at interior points \(z_k=kL/(K+1)\), then the paper's discrete-space approximation is
\[
\lambda_{1,K}:=-\frac{\pi^2D}{L^2}+\frac{2}{K+1}\sum_{k=1}^{K}g_k\sin^2\left(\frac{k\pi}{K+1}\right),
\]
where \(g_k\) is the growth value assigned to the \(k\)-th interior subinterval or grid point.

\textbf{Premises.}
\begin{align*}
(P1)\quad & L>0,
\quad D>0,
\quad K\in\mathbb{N},
\quad h_z:=\frac{L}{K+1},
\quad z_k:=kh_z=\frac{kL}{K+1}.\\
(P2)\quad & g_k:=g(z_k)\quad\text{or the piecewise-constant value of }g\text{ on the }k\text{-th interior cell}.\\
(P3)\quad & \lambda_1\approx -\frac{\pi^2D}{L^2}+\frac{2}{L}\int_0^L g(z)\sin^2\left(\frac{\pi z}{L}\right)\,dz.\\
(P4)\quad & \int_0^L g(z)\sin^2\left(\frac{\pi z}{L}\right)\,dz\approx h_z\sum_{k=1}^{K}g_k\sin^2\left(\frac{\pi z_k}{L}\right).\\
(P5)\quad & \lambda_{1,K}:=-\frac{\pi^2D}{L^2}+\frac{2}{L}h_z\sum_{k=1}^{K}g_k\sin^2\left(\frac{\pi z_k}{L}\right).
\end{align*}

\textbf{Derivation.}
\begin{align*}
\lambda_1
&\approx -\frac{\pi^2D}{L^2}+\frac{2}{L}\int_0^L g(z)\sin^2\left(\frac{\pi z}{L}\right)\,dz && \text{by }(P3)\\
&\approx -\frac{\pi^2D}{L^2}+\frac{2}{L}h_z\sum_{k=1}^{K}g_k\sin^2\left(\frac{\pi z_k}{L}\right) && \text{by }(P4)\\
&=\lambda_{1,K} && \text{by }(P5).
\end{align*}
Now substitute the grid definitions:
\begin{align*}
\lambda_{1,K}
&=-\frac{\pi^2D}{L^2}+\frac{2}{L}h_z\sum_{k=1}^{K}g_k\sin^2\left(\frac{\pi z_k}{L}\right) && \text{by }(P5)\\
&=-\frac{\pi^2D}{L^2}+\frac{2}{L}\frac{L}{K+1}\sum_{k=1}^{K}g_k\sin^2\left(\frac{\pi}{L}\frac{kL}{K+1}\right) && \text{by }(P1)\\
&=-\frac{\pi^2D}{L^2}+\frac{2}{K+1}\sum_{k=1}^{K}g_k\sin^2\left(\frac{k\pi}{K+1}\right). && \text{algebra}
\end{align*}

\textbf{Final Result.}
\[
\boxed{\displaystyle
\lambda_{1,K}:=-\frac{\pi^2D}{L^2}+\frac{2}{K+1}\sum_{k=1}^{K}g_k\sin^2\left(\frac{k\pi}{K+1}\right)}
\]
\hfill$\blacksquare$
